/* Nichinichi classroom and interface. Original implementation; no third-party app code. */
'use strict';
const CLASS_STEPS=[['词汇与复习',7,'先回忆，再认识四个常用词'],['读音与节奏',4,'听清一点，再读出一点'],['一个语法重点',5,'用两句话找回句子结构'],['自己造一句',4,'把表达换成自己的生活'],['听懂，再开口',7,'先听对话，再看文本跟读'],['三题小复习',3,'检查理解，留下需要再练的地方']];
let classSnapshot=null;
function finishedLessonIds(){return new Set(Object.entries(state.classDays).filter(([date,d])=>date<=today&&d.done.length===6).map(([,d])=>d.lessonId));}
function showLessonArchive(){const finished=finishedLessonIds();modal('基础恢复 · 课程回顾',window.DAILY_LESSONS.map(l=>`<details class="lesson-archive"><summary>${esc(l.title)} · ${finished.has(l.id)?'已完成练习':'可预习'}</summary><p class="subtext">${esc(l.grammar.explanation)}</p>${l.grammar.examples.map(lessonExample).join('')}<p class="subtext">本课词汇：${l.words.map(w=>esc(w.word)+'（'+esc(w.reading)+'）').join('、')}</p></details>`).join('')+'<p class="panel-note">查看课程不改变掌握状态。可以配合词卡、短文和阶段测评继续复习。</p>');}

function classroomDay(){
  if(!state.classDays[today]){
    const past=Object.entries(state.classDays).filter(([date])=>date<today).sort((a,b)=>b[0].localeCompare(a[0]));
    const finished=new Set(past.filter(([,d])=>d.done.length===6).map(([,d])=>d.lessonId));
    const next=window.DAILY_LESSONS.find(l=>!finished.has(l.id))||window.DAILY_LESSONS[6];
    const prior=finished.has(next.id)?null:past.find(([,d])=>d.lessonId===next.id&&d.done.length<6)?.[1];
    state.classDays[today]=prior?{...prior,done:[...prior.done],quiz:[...prior.quiz],touched:false}:{lessonId:next.id,step:0,done:[],draft:'',modelShown:false,transcriptShown:false,listenAnswer:null,listenChecked:false,quiz:[null,null,null],quizChecked:false,touched:false};
  }
  return state.classDays[today];
}
function currentLesson(){return window.DAILY_LESSONS.find(l=>l.id===classroomDay().lessonId);}
function applyAppearance(){const body=document.body||$('body');if(body){if(!body.dataset)body.dataset={};body.dataset.theme=state.preferences.theme;body.dataset.font=state.preferences.font;}const dark=state.preferences.theme==='dark'||(state.preferences.theme==='auto'&&window.matchMedia?.('(prefers-color-scheme: dark)').matches);const meta=$('meta[name="theme-color"]');if(meta?.setAttribute)meta.setAttribute('content',dark?'#212121':'#ffffff');}
window.matchMedia?.('(prefers-color-scheme: dark)')?.addEventListener?.('change',applyAppearance);
function activityOn(date){const d=state.days[date],c=state.classDays[date];return !!(c?.touched||(d&&(d.focusSeconds>0||d.seen.length||Object.values(d.tasks).some(Boolean))));}
function learningDates(){return [...new Set([...Object.keys(state.days),...Object.keys(state.classDays)])].filter(activityOn);}
function reviewForecast(){return Array.from({length:7},(_,i)=>{const date=addDays(today,i);return {date,count:Object.values(state.reviews).filter(r=>i===0?r.due<=date:r.due===date).length};});}
function forecastMarkup(){const rows=reviewForecast(),max=Math.max(1,...rows.map(r=>r.count));return `<div class="review-forecast">${rows.map((r,i)=>`<div class="forecast-col"><strong>${r.count}</strong><div class="forecast-track"><div class="forecast-fill" style="height:${r.count/max*100}%"></div></div><span class="forecast-label">${i===0?'今天':r.date.slice(5).replace('-','/')}</span></div>`).join('')}</div><p class="panel-note">按现有词卡到期日预览；今天包含逾期词。完成复习后会重新安排。</p>`;}
function recentActivity(){return `<div class="week-activity">${Array.from({length:14},(_,i)=>{const date=addDays(today,i-13),active=activityOn(date);return `<div class="activity-cell ${active?'is-active':''} ${date===today?'is-today':''}" title="${date} · ${active?'有学习记录':'暂无记录'}" aria-label="${date} ${active?'有学习记录':'暂无记录'}"><span>${new Date(date+'T12:00:00').getDate()}</span></div>`;}).join('')}</div>`;}
function latestWrongWords(){const latest=new Map();state.wordPractice.forEach(r=>latest.set(r.id,r));return vocab().filter(v=>latest.get(v.id)?.correct===false);}

renderToday=function(){
  const d=currentDay(),c=classroomDay(),lesson=currentLesson(),due=getDue().length,weekReview=new Date(today+'T12:00:00').getDay()===0;
  const count=c.done.length,stage=DATA.plan.phases[state.phase];
  return `${heading('今天，也和日语见一面。','每天一点，慢慢恢复。你的目标：JLPT N2。','基础优先 · 每天 '+state.minutes+' 分钟')}
  <section class="daily-hero"><div class="hero-copy"><span class="dashboard-eyebrow">NICHI NICHI / YOUR DAILY PRACTICE</span><h2>把日语，<br>一点点找回来。</h2><p>${finishedLessonIds().size===7?'7 节起始微课已练过，今天回顾熟悉的表达。':'今天从「'+esc(lesson.title)+'」开始。'}<br>一个小课堂，六个轻量练习。</p><div class="button-row"><button class="button" data-action="class-open">${count===6?'回看本课':count||c.draft?'继续我的课堂':'开始 30 分钟课堂'} <span aria-hidden="true">↗</span></button><button class="button ghost" data-action="study-tab" data-id="vocabulary">${due?'先复习 '+due+' 个到期词':'打开词卡'}</button></div></div><div class="hero-orbit" aria-hidden="true"><span>日々</span><small>一歩ずつ。</small><i>あ</i><i>の</i><i>学</i></div></section>
  <div class="stats"><div class="stat"><div class="stat-icon" aria-hidden="true">◷</div><div><small>今日实际专注</small><strong>${Math.floor(d.focusSeconds/60)}<span>分钟</span></strong></div></div><div class="stat"><div class="stat-icon" aria-hidden="true">↻</div><div><small>到期复习</small><strong>${due}<span>个词</span></strong></div></div><div class="stat"><div class="stat-icon" aria-hidden="true">文</div><div><small>接触过的词</small><strong>${Object.keys(state.reviews).length}<span>个</span></strong></div></div><div class="stat"><div class="stat-icon" aria-hidden="true">✦</div><div><small>有记录的学习日</small><strong>${learningDates().length}<span>天</span></strong></div></div></div>
  <div class="today-layout"><div><section class="card"><div class="card-head"><div><span class="dashboard-eyebrow">TODAY'S CLASSROOM</span><h2>今天，跟着这六步学</h2></div><span class="pill">本课 ${count} / 6</span></div><div class="daily-progress"><progress value="${count}" max="6" aria-label="本课完成环节"></progress><p class="subtext">${esc(lesson.title)} · 总计约 30 分钟，可分次完成</p></div><div class="lesson-path">${CLASS_STEPS.map(([title,minutes,hint],i)=>`<button class="lesson-step ${c.done.includes(i)?'is-done':''} ${c.step===i?'is-current':''}" data-action="class-step" data-id="${i}" aria-label="第${i+1}步 ${title} ${c.done.includes(i)?'已完成':'待完成'}"><span class="step-index">${c.done.includes(i)?'✓':String(i+1).padStart(2,'0')}</span><span class="step-copy"><strong>${title}</strong><small>${hint}</small></span><span class="step-state">${minutes} 分钟 <span aria-hidden="true">↗</span></span></button>`).join('')}</div><p class="panel-note">环节完成由练习提交与自行确认记录，不代表已经掌握。剩余内容会留到下次。</p></section>
  <section class="card"><div class="card-head"><h2>学习工具，随时打开</h2><small>按照你的节奏选</small></div><div class="quick-actions"><button class="quick-action" data-action="word-audio-library"><span aria-hidden="true">あ</span><strong>词库与查词</strong><small>4,790 个词 · 按主题筛选</small></button><button class="quick-action" data-action="word-drill-start"><span aria-hidden="true">♪</span><strong>真人词音听写</strong><small>一次 5 词 · 输入假名</small></button><button class="quick-action" data-action="academy-mistakes"><span aria-hidden="true">↻</span><strong>回看易忘词</strong><small>查看最新听写错词与薄弱词</small></button><button class="quick-action" data-action="study-tab" data-id="reading"><span aria-hidden="true">読</span><strong>在短文里学词</strong><small>阅读理解 · 重点词收藏</small></button></div></section>
  <section class="card"><div class="card-head"><h2>最近两周的小积累</h2><small>有学习记录的日子</small></div>${recentActivity()}<p class="panel-note">记录来自词卡、课堂练习、任务确认或专注计时。打开页面不会计为学习。</p></section></div>
  <aside><section class="card focus-callout"><span class="dashboard-eyebrow">REVIEW FIRST</span><h2>${due?'先和熟悉的词再见一面。':'给记忆留一点时间。'}</h2><p class="subtext">${due?'今天有 '+due+' 个词待复习，复习较多时可以暂停新词。':weekReview?'今天是复习日，回看本周学过的词和笔记。':'每天最多 5 个新词，先完成到期复习。'}</p><div class="button-row"><button class="button full" data-action="study-tab" data-id="vocabulary">${due?'开始复习':'打开词卡'} →</button><button class="button ghost full" data-action="timer">◷ 专注计时</button></div></section>
  ${!state.diagnostic?'<section class="card course-mini"><h2>先找到你的起点</h2><p class="subtext">8道基础小题，了解哪些知识需要恢复。听力和口语另行评估。</p><button class="text-link" data-action="diagnostic">做基础小测 →</button></section>':''}
  <section class="card"><div class="card-head"><h2>接下来一周的复习</h2></div>${forecastMarkup()}</section><section class="card course-mini"><span class="dashboard-eyebrow">YOUR NEXT STOP</span><h2>${esc(stage.title.replace(/第 \d 阶段 · /,''))}</h2><p class="subtext">${esc(stage.focus)}</p><button class="text-link" data-action="plan">查看我的备考路线 →</button></section></aside></div>`;
};

const originalRenderStudy=renderStudy;
renderStudy=function(){
  if(studyTab==='classroom')return renderClassroom();
  return `<div class="classroom-resume"><button class="text-link" data-action="class-open">← 回到我的 30 分钟课堂</button><button class="text-link" data-action="academy-appearance">显示设置</button></div>`+originalRenderStudy();
};
function lessonExample(e){return `<div class="lesson-example"><p class="jp" lang="ja">${esc(e.jp)}</p><p class="reading" lang="ja">${esc(e.reading)}</p><p class="translation">${esc(e.zh)}</p></div>`;}
function lessonWord(w){return vocab().find(v=>v.word===w.word&&v.reading===w.reading);}
function classChoices(q,kind,selected,checked,index=0){return `<div class="lesson-quiz"><h3>${esc(q.prompt)}</h3>${q.choices.map((text,i)=>`<button class="choice ${selected===i?'selected':''} ${checked&&i===q.answer?'correct':checked&&selected===i?'wrong':''}" data-action="${kind}" data-id="${index}:${i}" aria-pressed="${selected===i}" ${checked?'disabled':''}><b>${'ABC'[i]}</b><span>${esc(text)}</span></button>`).join('')}${checked?`<div class="feedback ${selected===q.answer?'':'wrong'}"><strong>${selected===q.answer?'答对了':'再看一下这个区别'}</strong><p>${esc(q.explanation)}</p></div>`:''}</div>`;}
function classBody(l,c){
  if(c.step===0)return `<p class="subtext">先用两分钟回忆到期词，再从下面选择需要恢复的词。已会的可以略过。</p><button class="button secondary" data-action="study-tab" data-id="vocabulary">先复习到期词（${getDue().length}） →</button><div class="lesson-word-grid section-gap">${l.words.map(w=>{const v=lessonWord(w);return `<article class="lesson-word"><span class="pill">${esc(w.pos)}</span><h3 class="jp" lang="ja">${esc(w.word)}</h3><p class="reading" lang="ja">${esc(w.reading)}</p><p>${esc(w.meaning)}</p><p class="subtext">${esc(w.collocation)}</p><div class="lesson-example"><p class="jp" lang="ja">${esc(w.example)}</p><p class="reading" lang="ja">${esc(w.exampleReading)}</p><p class="translation">${esc(w.zh)}</p></div>${v?`<div class="button-row"><button class="button ghost" data-action="speak-word" data-id="${v.id}">${wordAudioButtonLabel(v)}</button><button class="text-link" data-action="class-save-word" data-id="${v.id}" ${state.reviews[v.id]||state.priorityWords.includes(v.id)?'disabled':''}>${state.reviews[v.id]?'已在复习中':state.priorityWords.includes(v.id)?'已加入优先新词':'＋ 优先学习'}</button></div>`:''}</article>`;}).join('')}</div><p class="panel-note">加入优先新词不会直接标记为学会，也不会突破每日 5 个新词上限。</p>`;
  if(c.step===1)return `<h3>${esc(l.sound.title)}</h3><p>${esc(l.sound.tip)}</p>${l.sound.pairs.map((p,i)=>`${lessonExample(p)}<button class="button ghost" data-action="class-sound" data-id="${i}">▷ 听示范 · 设备合成</button>`).join('')}<p class="panel-note">慢读两遍，再用正常速度读一遍。此处提供示范，没有自动发音评分。</p>`;
  if(c.step===2)return `<h3 class="grammar-title">${esc(l.grammar.title)}</h3><p>${esc(l.grammar.explanation)}</p>${l.grammar.examples.map(lessonExample).join('')}<p class="panel-note">试着遮住例句，用自己的信息替换其中一个词。</p>`;
  if(c.step===3)return `<h3>${esc(l.production.prompt)}</h3><p class="subtext">${esc(l.production.hint)}</p><label for="class-draft">写下你的日语<textarea id="class-draft" maxlength="2000" rows="4" lang="ja" placeholder="用你会的表达，先写一句。">${esc(c.draft)}</textarea></label><p class="panel-note">输入会保存在本机。这里不进行自动语法评分；可以对照参考句，或把原句交给老师批改。</p><button class="button secondary" data-action="class-model" ${!c.draft.trim()?'disabled':''}>写完后，查看一种参考表达</button>${c.modelShown?lessonExample({jp:l.production.model,reading:l.production.reading,zh:l.production.zh}):''}`;
  if(c.step===4)return `<p class="subtext">先听两遍，选出答案；再展开文本，分别扮演两个人朗读。</p><div class="audio-controls"><button class="button" data-action="class-play">▷ 播放对话 · 设备合成</button><button class="button ghost" data-action="stop-speech">停止</button><label for="class-audio-rate" class="visually-hidden">对话速度</label><select id="class-audio-rate"><option value="0.8" ${audioRate===0.8?'selected':''}>0.8 × 慢速</option><option value="1" ${audioRate===1?'selected':''}>1.0 × 正常</option><option value="1.15" ${audioRate===1.15?'selected':''}>1.15 × 稍快</option></select></div><p class="panel-note">需要设备安装日语声音。真人词音练习可从首页“听写”进入。</p>${classChoices(l.listenQuestion,'class-listen-choice',c.listenAnswer,c.listenChecked)}${!c.listenChecked?`<button class="button" data-action="class-listen-check" ${c.listenAnswer===null?'disabled':''}>核对答案</button>`:''}<button class="button ghost section-gap" data-action="class-transcript">${c.transcriptShown?'收起文本':'查看文本与翻译'}</button>${c.transcriptShown?`<div class="lesson-transcript">${l.dialogue.map((e,i)=>`<div><span class="pill">${esc(e.speaker)}</span>${lessonExample(e)}<button class="text-link" data-action="class-line" data-id="${i}">▷ 单句跟读 · 设备合成</button></div>`).join('')}</div>`:''}`;
  const score=l.quiz.filter((q,i)=>q.answer===c.quiz[i]).length;
  return `<p class="subtext">先独立完成三题，提交后再看解释。错题会自动留在积累手账。</p>${l.quiz.map((q,i)=>classChoices(q,'class-quiz-choice',c.quiz[i],c.quizChecked,i)).join('')}<div class="button-row">${c.quizChecked?`<p class="feedback">本次答对 ${score} / 3 题。这只反映本课练习情况。</p><button class="button ghost" data-action="class-quiz-retry">遮住答案，再练一遍</button>`:`<button class="button" data-action="class-quiz-check" ${c.quiz.some(x=>x===null)?'disabled':''}>提交这三题</button>`}</div>`;
}
function renderClassroom(){const c=classroomDay(),l=currentLesson(),[title,mins]=CLASS_STEPS[c.step];classSnapshot={date:today,lessonId:l.id};return `${heading((finishedLessonIds().size===7?'复习 · ':'')+l.title,l.subtitle,finishedLessonIds().size===7?'起始模块已完成':'基础恢复 · 第 '+Number(l.id.slice(-2))+' / 7 课')}<div class="classroom-resume"><button class="text-link" data-action="today">← 回到今日学习</button><button class="text-link" data-action="timer">◷ 打开专注计时</button></div><div class="classroom-layout"><section class="card"><div class="card-head"><h2>${c.step+1}. ${title}</h2><span class="pill">约 ${mins} 分钟</span></div>${classBody(l,c)}<div class="classroom-footer"><button class="button ghost" data-action="class-step" data-id="${Math.max(0,c.step-1)}" ${c.step===0?'disabled':''}>上一步</button><button class="button" data-action="class-complete">${c.done.includes(c.step)?c.step===5?'回看学习摘要':'继续下一步 →':c.step===5?'完成本课，查看摘要':'练习完成，下一步 →'}</button></div><p class="panel-note">课堂进度会保留。完成确认不等于掌握；词卡复习、实际专注时间分别记录。</p></section><aside><section class="card"><h2>每次只做一小步</h2><progress class="lesson-progress" value="${c.done.length}" max="6" aria-label="本课完成环节"></progress><div class="lesson-path">${CLASS_STEPS.map(([name,time],i)=>`<button class="lesson-step ${c.step===i?'is-current':''} ${c.done.includes(i)?'is-done':''}" data-action="class-step" data-id="${i}" ${c.step===i?'aria-current="step"':''}><span class="step-index">${c.done.includes(i)?'✓':i+1}</span><span class="step-copy"><strong>${name}</strong><small>${time} 分钟</small></span></button>`).join('')}</div></section><section class="card course-mini"><h2>基础恢复 · 7 节微课</h2><ol class="info-list">${window.DAILY_LESSONS.map(item=>`<li ${item.id===l.id?'aria-current="true"':''}>${esc(item.title)}</li>`).join('')}</ol><p class="panel-note">按完成情况逐课推进，不因漏学一天跳过内容。这是起始模块，后续配合备考路线继续学习。</p><button class="text-link" data-action="academy-archive">查看七课内容 →</button></section></aside></div>`;}
function guardClass(){if(dayKey()!==today){render();toast('日期已更新，请在今天的课堂继续。');return false;}if(classSnapshot&&(classSnapshot.date!==today||classSnapshot.lessonId!==classroomDay().lessonId)){render();return false;}return true;}
function finishClassStep(){const c=classroomDay();if(c.step===3&&!c.draft.trim())return toast('先用日语写下一句，再继续。');if(c.step===4&&!c.listenChecked)return toast('先选择并核对听力题。');if(c.step===5&&!c.quizChecked)return toast('先完成并提交三道复习题。');if(!c.done.includes(c.step))c.done.push(c.step);c.touched=true;if(c.step<5){c.step++;persist();render();window.scrollTo({top:0,behavior:'instant'});}else{const l=currentLesson();const score=l.quiz.filter((q,i)=>q.answer===c.quiz[i]).length;addNote('class-'+today+'-'+l.id,'课堂记录：'+l.title,`完成环节：${c.done.length}/6\n本次小测：${score}/3\n我的造句：${c.draft||'尚未填写'}\n下次：回忆本课单词，重做易错题。听说能力需另行评估。`,'课堂');persist();render();modal('把今天学到的留下来',`<h3>${esc(l.title)}</h3><p>本课完成 ${c.done.length} / 6 个环节，小测答对 ${score} / 3 题。</p><p class="subtext">造句和测验记录已保存在积累手账。${c.done.length===6?(finishedLessonIds().size===7?'7节起始微课已完成；接下来可回顾课程、做阶段测评，并按备考路线继续学习。':'下一次学习日将安排下一课。'):'还有未完成的环节，可以回到课堂补练。'}</p><div class="button-row"><button class="button" data-action="class-summary-close">回到课堂</button><button class="button ghost" data-action="export">导出学习备份</button></div>`);}}

renderVocabulary=function(){if(!queueActive)buildQueue();const v=vocab().find(v=>v.id===queue[0]),reverse=state.preferences.recall==='meaning';return `<div class="flashcard-tools"><div class="recall-toggle" role="group" aria-label="词卡回忆方向"><button class="tab ${!reverse?'active':''}" data-action="academy-recall" data-id="word" aria-pressed="${!reverse}">日语 → 中文</button><button class="tab ${reverse?'active':''}" data-action="academy-recall" data-id="meaning" aria-pressed="${reverse}">中文 → 日语</button></div><button class="button ghost" data-action="word-audio-library">查词与词库 ↗</button></div><div class="split"><div><section class="card study-card"><div class="status-row full"><span>${v?(state.reviews[v.id]?'到期复习':'今日新词'):'今日词卡'}</span><span>${queue.length} 张待学</span></div>${v?`<span class="pill">${stageTitle(v)}</span><div class="word ${reverse?'reverse-word':'jp'}" ${reverse?'':'lang="ja"'}>${esc(reverse?v.meaning:v.word)}</div>${!reverse||cardRevealed?`<button class="button secondary" data-action="speak-word" data-id="${esc(v.id)}">${wordAudioButtonLabel(v)}</button>`:''}${cardRevealed?`<div class="answer">${reverse?`<div class="word jp" lang="ja">${esc(v.word)}</div>`:''}<div class="reading jp" lang="ja">${esc(v.reading)}</div>${reverse?'':`<div class="meaning">${esc(v.meaning)}</div>`}${vocabularyDetail(v)}${wordVoiceLinks(v)}</div><div class="button-row full rating-actions"><button class="button orange" data-action="rate" data-id="again">忘了 · 再练</button><button class="button ghost" data-action="rate" data-id="hard">不熟 · 明天</button><button class="button" data-action="rate" data-id="good">记得 · 下一张</button></div>`:`<p class="subtext section-gap">${reverse?'试着说出日语单词和读音，再核对答案。':'先回想读音和意思，再翻开答案。'}</p><button class="button section-gap full" data-action="reveal-card">翻开词卡 ↓</button>`}`:`<div class="empty"><h2>今天的词卡，先到这里。</h2><p>${new Date(today+'T12:00:00').getDay()===0?'周日只复习旧词。':'每日最多 5 个新词；复习会按到期日回来。'}</p><button class="button" data-action="complete-vocab">完成词汇任务</button></div>`}</section><p class="study-shortcuts">电脑快捷键：空格翻卡 · 1 忘了 · 2 不熟 · 3 记得 · P 播放读音</p><p class="panel-note">到期词优先。记得后按 1 → 3 → 7 → 14 → 30 天复习；忘了则当天再练。</p></div><aside><section class="card"><h2>按自己的记忆来选择</h2><p class="subtext">看到答案后的熟悉感，不等于能自己想起来。复习时间较长时，可以先停下来，剩余词卡仍会保留。</p><div class="button-row"><button class="button secondary" data-action="academy-mistakes">回看易忘词</button><button class="button ghost" data-action="add-word">＋ 添加单词</button></div></section>${wordAudioResourceCard()}</aside></div><details class="card"><summary>词库进度、教材主题与数据来源</summary>${vocabularyOverview()}</details>`;};

function showMistakes(){const wrong=latestWrongWords(),weak=vocab().filter(v=>state.reviews[v.id]&&state.reviews[v.id].stage<1),all=[...new Map([...wrong,...weak].map(v=>[v.id,v])).values()];modal('把容易忘的，再练一次',`<p class="subtext">${wrong.length} 个最近听写错误的词，${weak.length} 个处于初步记忆阶段的词。听写以最近一次结果为准。</p><div class="button-row"><button class="button" data-action="academy-retry-wrong" ${!wrong.length?'disabled':''}>重练有录音的听写错词</button><button class="button ghost" data-action="academy-due-review">复习今天到期词</button></div>${all.slice(0,30).map(v=>`<article class="library-entry"><div class="library-word"><strong class="jp" lang="ja">${esc(v.word)}</strong><button class="button ghost" data-action="speak-word" data-id="${esc(v.id)}">${wordAudioButtonLabel(v)}</button></div><p class="reading" lang="ja">${esc(v.reading)}</p><p>${esc(v.meaning)}</p><span class="pill">${wrong.some(w=>w.id===v.id)?'最近听写待巩固':'初步记忆中'}</span></article>`).join('')||'<p class="empty">暂时没有待巩固的词，完成一轮词卡或听写后再来看看。</p>'}${all.length>30?'<p class="panel-note">这里先显示30个；完整内容可在词库按状态查看。</p>':''}`);}
function retryWrongWords(){const words=latestWrongWords().filter(v=>/^[ぁ-ゖー]+$/u.test(kanaKey(v.reading))&&(bundledWordRecording(v)||hasWordRecording(v.id))).slice(0,5);if(!words.length)return toast('这些错词暂时没有可用录音，可先在词卡里复习。');stopWordAudio();wordDrill={ids:words.map(v=>v.id),index:0,answers:[],checked:false,input:''};renderWordDrill();}
function appearanceMarkup(){return `<section><h3>适合你的阅读方式</h3><div class="form-grid appearance-options"><label>页面主题<select id="academy-theme"><option value="auto" ${state.preferences.theme==='auto'?'selected':''}>跟随系统</option><option value="light" ${state.preferences.theme==='light'?'selected':''}>浅色 · 灰白</option><option value="dark" ${state.preferences.theme==='dark'?'selected':''}>深色 · 炭灰</option></select></label><label>文字大小<select id="academy-font"><option value="normal" ${state.preferences.font==='normal'?'selected':''}>标准字号</option><option value="large" ${state.preferences.font==='large'?'selected':''}>大字阅读</option></select></label></div></section>`;}
const originalSettings=settings;
settings=function(){originalSettings();$('#modal-content').innerHTML+=`<div class="section-gap">${appearanceMarkup()}</div>`;};
const originalRender=render;
render=function(){applyAppearance();originalRender();};
const originalRateCard=rateCard;
rateCard=function(rating){if(dayKey()!==today){render();toast('日期已更新，请重新确认当前词卡。');return;}originalRateCard(rating);};
const originalRenderReading=renderReading;
renderReading=function(){const html=originalRenderReading(),maps={'foundation-reading-01':['毎晩','復習','会話','言葉'],'foundation-reading-02':['図書館','参加','必要','物語']},words=(maps[readingId]||[]).map(word=>vocab().find(v=>v.word===word)).filter(Boolean);return html+`<section class="card"><h2>把短文里的词留下来</h2><p class="subtext">读完后再查四个重点词，把不熟的加入优先新词。</p><div class="button-row">${words.map(v=>`<button class="button ghost jp" lang="ja" data-action="academy-context-word" data-id="${v.id}">${esc(v.word)} ↗</button>`).join('')}</div></section>`;};

document.addEventListener('click',e=>{
  const el=e.target.closest('[data-action]');if(!el||el.disabled)return;const {action,id}=el.dataset;
  if(action.startsWith('class-')&&!['class-open','class-step','class-summary-close'].includes(action)&&!guardClass())return;
  if(action==='class-open'||action==='class-step'){if(dayKey()!==today)render();if(id!==undefined){const n=Number(id);if(Number.isInteger(n)&&n>=0&&n<6)classroomDay().step=n;}persist();study('classroom');return;}
  if(action==='class-summary-close'){$('#modal').close();return;}
  if(action==='class-save-word'){if(!state.reviews[id]&&!state.priorityWords.includes(id)&&vocab().some(v=>v.id===id)){state.priorityWords.push(id);queueActive=false;persist();render();toast('已加入优先新词，每天最多学习5个。');}return;}
  if(action.startsWith('class-')){const c=classroomDay(),l=currentLesson();
    if(action==='class-complete'){finishClassStep();return;}
    if(action==='class-model'){if(c.draft.trim())c.modelShown=true;else return;}
    if(action==='class-transcript')c.transcriptShown=!c.transcriptShown;
    if(action==='class-sound'){const p=l.sound.pairs[Number(id)];if(p){stopWordAudio();speak(p.reading,0.8);}return;}
    if(action==='class-play'){stopWordAudio();speak(l.dialogue.map(x=>x.jp).join('。'),audioRate);return;}
    if(action==='class-line'){const line=l.dialogue[Number(id)];if(line){stopWordAudio();speak(line.jp,audioRate);}return;}
    if(action==='class-listen-choice'&&!c.listenChecked){const answer=Number(id.split(':')[1]);if(answer>=0&&answer<=2)c.listenAnswer=answer;}
    if(action==='class-listen-check'){if(c.listenAnswer===null||c.listenChecked)return;c.listenChecked=true;c.touched=true;if(c.listenAnswer!==l.listenQuestion.answer)addNote('class-listen-'+l.id,'课堂听力：'+l.title,l.listenQuestion.prompt+'\n'+l.listenQuestion.explanation,'听力');}
    if(action==='class-quiz-choice'&&!c.quizChecked){const [index,answer]=id.split(':').map(Number);if(index>=0&&index<3&&answer>=0&&answer<3)c.quiz[index]=answer;}
    if(action==='class-quiz-check'){if(c.quiz.some(x=>x===null)||c.quizChecked)return;c.quizChecked=true;c.touched=true;l.quiz.forEach((q,i)=>{if(c.quiz[i]!==q.answer)addNote('class-quiz-'+l.id+'-'+i,'课堂错题：'+l.title,q.prompt+'\n正确答案：'+q.choices[q.answer]+'\n'+q.explanation,'课堂错题');});}
    if(action==='class-quiz-retry'){c.quiz=[null,null,null];c.quizChecked=false;c.done=c.done.filter(x=>x!==5);}
    persist();render();return;
  }
  if(action==='academy-recall'){if(['word','meaning'].includes(id)){state.preferences.recall=id;cardRevealed=false;persist();render();}return;}
  if(action==='academy-appearance'){modal('显示设置',appearanceMarkup());return;}
  if(action==='academy-archive'){showLessonArchive();return;}
  if(action==='academy-mistakes'){showMistakes();return;}
  if(action==='academy-retry-wrong'){retryWrongWords();return;}
  if(action==='academy-due-review'){$('#modal').close();study('vocabulary');return;}
  if(action==='academy-context-word'){const v=vocab().find(w=>w.id===id);if(v)modal('短文里的重点词',`<h3 class="jp">${esc(v.word)}</h3><p class="reading jp">${esc(v.reading)}</p><p>${esc(v.meaning)}</p>${vocabularyDetail(v)}<div class="button-row"><button class="button" data-action="speak-word" data-id="${v.id}">${wordAudioButtonLabel(v)}</button><button class="button ghost" data-action="academy-context-save" data-id="${v.id}" ${state.reviews[id]||state.priorityWords.includes(id)?'disabled':''}>${state.reviews[id]?'已在复习中':state.priorityWords.includes(id)?'已加入优先新词':'＋ 优先学习'}</button></div>`);return;}
  if(action==='academy-context-save'){if(!state.reviews[id]&&!state.priorityWords.includes(id)&&vocab().some(w=>w.id===id)){state.priorityWords.push(id);queueActive=false;persist();toast('已加入优先新词。');el.disabled=true;el.textContent='已加入优先新词';}return;}
});
document.addEventListener('input',e=>{if(e.target.id==='class-draft'){if(!guardClass())return;const c=classroomDay();c.draft=e.target.value.slice(0,2000);c.touched=true;persist();const btn=document.querySelector('[data-action="class-model"]');if(btn)btn.disabled=!c.draft.trim();}});
document.addEventListener('change',e=>{if(e.target.id==='academy-theme'&&['auto','light','dark'].includes(e.target.value)){state.preferences.theme=e.target.value;persist();applyAppearance();}if(e.target.id==='academy-font'&&['normal','large'].includes(e.target.value)){state.preferences.font=e.target.value;persist();applyAppearance();}if(e.target.id==='class-audio-rate'&&[0.8,1,1.15].includes(Number(e.target.value)))audioRate=Number(e.target.value);});
document.addEventListener('keydown',e=>{if(route!=='study'||studyTab!=='vocabulary'||$('#modal').open||e.ctrlKey||e.metaKey||e.altKey||e.repeat||e.isComposing||e.target?.closest?.('input,textarea,select,button,a,[contenteditable="true"]'))return;const key=e.key.toLowerCase();if(![' ','1','2','3','p'].includes(key))return;e.preventDefault();if(dayKey()!==today){render();return;}if(!queue.length)return;if(key===' '&&!cardRevealed){cardRevealed=true;render();}else if(['1','2','3'].includes(key)&&cardRevealed)rateCard({'1':'again','2':'hard','3':'good'}[key]);else if(key==='p'){const v=vocab().find(w=>w.id===queue[0]);if(v)playWordAudio(v);}});
render();
